/* C1 is the academic core followed by the thematic domains, the register
 * groups and the false friends. They were held back as `*_STAGED` until they
 * had been checked; every headword in both halves has since been verified
 * against the language's own Wiktionary, and the German compounds it does not
 * list against the DWDS corpus (scripts/audit-c1.mjs). Order matters — the
 * core is what the level is *for*, so it comes first. */
export const DATA = {
  fr: { A1: FR_A1, A2: FR_A2, B1: FR_B1, B2: FR_B2, C1: [...FR_C1, ...FR_C1_STAGED] },
  de: { A1: DE_A1, A2: DE_A2, B1: DE_B1, B2: DE_B2, C1: [...DE_C1, ...DE_C1_STAGED] },
};

/** Every vocabulary level the app knows about, in order. */
export const LEVELS = ["A1", "A2", "B1", "B2", "C1"];

/* Reading passages, idioms and dictation only exist for A1–B2. Those pickers
 * iterate this list instead of LEVELS, so adding a vocabulary-only level can't
 * offer a lesson that isn't there. */
export const CORE_LEVELS = ["A1", "A2", "B1", "B2"];

/**
 * Levels that can be listened to — every level whose words carry an example
 * sentence and a translation.
 *
 * Dictation was pinned to CORE_LEVELS along with reading and idioms, which was
 * right when C1 had no sentences. It has 1,038 in French and 1,207 in German
 * now, all hand-written, and none of them were reachable: a learner who
 * finished B2 dictation found the section simply stopped.
 */
export function audioLevelsFor(lang) {
  return LEVELS.filter((lv) =>
    (DATA[lang]?.[lv] || []).some((g) => (g.words || []).some((w) => w.s && w.se)));
}

/** The levels this language actually has words for. */
export function levelsFor(lang) {
  return LEVELS.filter((lv) => (DATA[lang]?.[lv] || []).length > 0);
}

export const LEVEL_INFO = {
  A1: { name: "Beginner", desc: "Greetings, family, numbers, colors, everyday basics" },
  A2: { name: "Elementary", desc: "Time, weather, shopping, travel, feelings, routine" },
  B1: { name: "Intermediate", desc: "Work, society, opinions, connectors, abstract ideas" },
  B2: { name: "Upper-intermediate", desc: "Argument, nuance, formal register, discourse markers" },
  C1: { name: "Advanced", desc: "Academic register and the machinery underneath it" },
};

/* C1 means something different in each language — French's difficulty is the
 * shared academic lexicon, German's is prefix verbs and verb government — so
 * the blurb varies where the level does. */
const LEVEL_INFO_BY_LANG = {
  fr: { C1: { name: "Advanced", desc: "The transdisciplinary academic lexicon and its collocations" } },
  de: { C1: { name: "Advanced", desc: "Präfixverben, Funktionsverbgefüge, and verb government" } },
};

export function levelInfo(lang, lv) {
  return LEVEL_INFO_BY_LANG[lang]?.[lv] || LEVEL_INFO[lv];
}
export const LANG_INFO = {
  fr: { name: "French", locale: "fr-FR", demo: ["bonjour", "merci", "au revoir"] },
  de: { name: "German", locale: "de-DE", demo: ["hallo", "danke", "tschüss"] },
};

export function flattenLevel(groups) {
  return groups.flatMap((g) => g.words);
}
